/*
 * Transcript layout. Every activity row — reasoning, shell run, tool call, or a
 * step a server already labeled — shares the agent message measure and its block
 * spacing, so thinking reads as one more block of the reply rather than
 * something pinned to the pane edge. The contract lives with the component.
 */
.happy-agent-activity-row {
    flex: none;
    /* The subject ellipsizes, so it is the one line that always reaches its
       boundary: it stops short of where prose wraps, or a truncated command
       reads as running off the surface. */
    padding: 8px 96px 8px 30px;
}

