.happy-agent-activity-row[data-motion^="calm"] {
    padding-right: 20px;
}

/* The running glyph turns slowly enough to say "still working" without
   competing with the words beside it. Same four-step turn, a quarter the
   rate. */
.happy-agent-activity[data-motion^="calm"] .happy-spinner[data-variant="circle"] {
    --happy-spinner-duration: 2000ms;
}

