const { createRequire } = require("module");
const req = createRequire("/Users/demo/Happy/Projects/happy-desktop/packages/happy-desktop-ui/package.json");
const { chromium } = req("playwright");
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1720, height: 1100 } });
  await page.goto("http://127.0.0.1:4310/#tool-motion-replay", { waitUntil: "domcontentloaded" });
  await page.waitForTimeout(1000);
  await page.locator("main select:not([aria-label])").nth(1).selectOption("4");
  await page.waitForTimeout(400);
  await page.locator("input[type=range]").evaluate((node) => {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
    setter.call(node, String(Math.round(node.max * 0.8)));
    node.dispatchEvent(new Event("change", { bubbles: true }));
  });
  await page.waitForTimeout(400);
  const probe = await page.evaluate(() => {
    const editText = document.querySelector("[data-presentation=\"fileDiff\"] .happy-agent-activity__file-summary .happy-agent-activity__text");
    const exploreText = document.querySelector("[data-presentation=\"exploration\"] .happy-agent-activity__text");
    const es = editText ? getComputedStyle(editText) : null;
    const xs = exploreText ? getComputedStyle(exploreText) : null;
    const review = document.querySelector("[data-review]");
    const rv = review ? getComputedStyle(review.querySelector(".happy-agent-activity__verb")) : null;
    const rt = review ? getComputedStyle(review.querySelector(".happy-agent-activity__text")) : null;
    const plainText = document.querySelector(".happy-agent-activity:not([data-review]) .happy-agent-activity__text");
    const pt = plainText ? getComputedStyle(plainText) : null;
    const spinDur = getComputedStyle(document.documentElement).getPropertyValue("--happy-spinner-duration");
    return {
      editFont: es ? `${es.fontFamily.slice(0,20)} ${es.fontSize} w${es.fontWeight}` : null,
      exploreFont: xs ? `${xs.fontFamily.slice(0,20)} ${xs.fontSize} w${xs.fontWeight}` : null,
      reviewVerbColor: rv?.color, reviewTextColor: rt?.color, plainTextColor: pt?.color,
    };
  });
  console.log(JSON.stringify(probe, null, 1));
  await page.screenshot({ path: ".context/qa/replica-style-fixes.png" });
  await browser.close();
})();
'

